"""Tensor-parallel linear layers (Megatron-style) implemented with public PyTorch APIs.

ColumnParallelLinear: weight matrix is split along its output (column of A = X @ A)
dimension; each rank computes a slice of the output which is then all-gathered along
the last dimension.  Bias is sharded the same way as the output dimension.

RowParallelLinear: weight matrix is split along its input (row of A) dimension; each
rank's ``forward`` receives only its own slice of the input (already scattered along
the last dimension) and produces a partial output; partial outputs are all-reduced
(summed).  Bias is replicated (full) on every rank and added after the reduction.
"""

import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F

__all__ = ["ColumnParallelLinear", "RowParallelLinear"]


def get_world_size():
    """World size of the current process group (1 when distributed is not in use)."""
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def get_rank():
    """Rank of the current process (0 when distributed is not in use)."""
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _split_along_last_dim(tensor, world_size, rank):
    if world_size == 1:
        return tensor
    chunks = torch.chunk(tensor, world_size, dim=-1)
    return chunks[rank].contiguous()


def _all_gather_last_dim(tensor):
    world_size = get_world_size()
    if world_size == 1:
        return tensor
    tensor = tensor.contiguous()
    gathered = [torch.empty_like(tensor) for _ in range(world_size)]
    dist.all_gather(gathered, tensor)
    gathered[get_rank()] = tensor
    return torch.cat(gathered, dim=-1).contiguous()


def _all_reduce_sum(tensor):
    world_size = get_world_size()
    if world_size == 1:
        return tensor
    tensor = tensor.clone().contiguous()
    dist.all_reduce(tensor, op=dist.ReduceOp.SUM)
    return tensor


class _GatherFromModelParallelRegion(torch.autograd.Function):
    """All-gather in the forward pass, split (keep own shard) in the backward pass."""

    @staticmethod
    def forward(ctx, input_):
        return _all_gather_last_dim(input_)

    @staticmethod
    def backward(ctx, grad_output):
        return _split_along_last_dim(grad_output, get_world_size(), get_rank())


class _ReduceFromModelParallelRegion(torch.autograd.Function):
    """All-reduce (sum) in the forward pass, identity in the backward pass."""

    @staticmethod
    def forward(ctx, input_):
        return _all_reduce_sum(input_)

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


class _CopyToModelParallelRegion(torch.autograd.Function):
    """Identity in the forward pass, all-reduce (sum) in the backward pass."""

    @staticmethod
    def forward(ctx, input_):
        return input_

    @staticmethod
    def backward(ctx, grad_output):
        return _all_reduce_sum(grad_output)


class ColumnParallelLinear(nn.Module):
    """Linear layer with the weight/bias sharded along the output dimension."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size = get_world_size()
        rank = get_rank()
        self.world_size = world_size
        self.rank = rank

        if out_features % world_size != 0:
            raise ValueError(
                "out_features (%d) must be divisible by world size (%d)"
                % (out_features, world_size)
            )
        self.output_size_per_partition = out_features // world_size

        master_weight = torch.as_tensor(master_weight)
        # Stored weight has shape (out_features, in_features); "splitting by columns"
        # of A (= W^T) means splitting the stored weight along dim 0.
        weight_shard = torch.chunk(master_weight.detach(), world_size, dim=0)[rank]
        self.weight = nn.Parameter(weight_shard.clone().contiguous())

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    self.output_size_per_partition,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        # Input is replicated on every rank: identity forward, all-reduce backward.
        input_parallel = _CopyToModelParallelRegion.apply(input_)
        output_parallel = F.linear(input_parallel, self.weight, self.bias)
        # Gather the output shards along the last dimension.
        return _GatherFromModelParallelRegion.apply(output_parallel)

    def extra_repr(self):
        return "in_features={}, out_features={}, bias={}".format(
            self.in_features, self.out_features, self.bias is not None
        )


class RowParallelLinear(nn.Module):
    """Linear layer with the weight sharded along the input dimension."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size = get_world_size()
        rank = get_rank()
        self.world_size = world_size
        self.rank = rank

        if in_features % world_size != 0:
            raise ValueError(
                "in_features (%d) must be divisible by world size (%d)"
                % (in_features, world_size)
            )
        self.input_size_per_partition = in_features // world_size

        master_weight = torch.as_tensor(master_weight)
        # Stored weight has shape (out_features, in_features); "splitting by rows"
        # of A (= W^T) means splitting the stored weight along dim 1.
        weight_shard = torch.chunk(master_weight.detach(), world_size, dim=1)[rank]
        self.weight = nn.Parameter(weight_shard.clone().contiguous())

        if bias:
            # Bias is not sharded: full bias replicated on every rank.
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        # ``input_`` is already the local slice of the input along the last dimension.
        output_parallel = F.linear(input_, self.weight)
        output = _ReduceFromModelParallelRegion.apply(output_parallel)
        if self.bias is not None:
            output = output + self.bias
        return output

    def extra_repr(self):
        return "in_features={}, out_features={}, bias={}".format(
            self.in_features, self.out_features, self.bias is not None
        )
